import{DesignSystemManager as e}from"../../d-d-d/lib/DesignSystemManager.js";import{ShadcnTokens as s,ShadcnFonts as n}from"./ShadcnTokens.js";import{ShadcnDDDMap as t}from"./ShadcnDDDMap.js";export const SHADCN_SYSTEM="shadcn";export function registerShadcnDesignSystem(a=e){return a&&!a.systems.shadcn&&a.addDesignSystem({name:"shadcn",extends:"ddd",styles:[s,t],fonts:n}),a}export function activateShadcnDesignSystem(s=e){return registerShadcnDesignSystem(s),s&&"shadcn"!==s.active&&(s.active="shadcn"),s}